import{_ as a,a0 as r,w as l,s as d,I as t,x as n,a1 as i,A as p,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理网络 | LCTT x X-CMD","titleTemplate":false,"description":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理网络 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理网络 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理网络 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/How to Manage Network using nmcli Tool in RedHat CentOS 7.x","title":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理网络","tag":"201505","desc":""},"relativePath":"201505/How to Manage Network using nmcli Tool in RedHat CentOS 7.x.md","filePath":"[post].md"}'),s={name:"201505/How to Manage Network using nmcli Tool in RedHat CentOS 7.x.md"};function c(u,e,g,C,x,N){const o=r("Link");return l(),d("div",null,[e[17]||(e[17]=t("h1",{id:"在-redhat-centos-7-x-中使用-nmcli-命令管理网络",tabindex:"-1"},[n("在 RedHat/CentOS 7.x 中使用 nmcli 命令管理网络 "),t("a",{class:"header-anchor",href:"#在-redhat-centos-7-x-中使用-nmcli-命令管理网络","aria-label":"Permalink to “在 RedHat/CentOS 7.x 中使用 nmcli 命令管理网络”"},"​")],-1)),t("p",null,[i(o,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/7.0_Release_Notes/"},{default:p(()=>[...e[0]||(e[0]=[t("strong",null,"Red Hat Enterprise Linux 7",-1),n(" 与 ",-1),t("strong",null,"CentOS 7",-1)])]),_:1}),e[1]||(e[1]=n(" 中默认的网络服务由 ",-1)),e[2]||(e[2]=t("strong",null,"NetworkManager",-1)),e[3]||(e[3]=n(" 提供，这是动态控制及配置网络的守护进程，它用于保持当前网络设备及连接处于工作状态，同时也支持传统的 ifcfg 类型的配置文件。",-1))]),e[18]||(e[18]=m(`<p>NetworkManager 可以用于以下类型的连接：Ethernet，VLANS，Bridges，Bonds，Teams，Wi-Fi，mobile boradband（如移动3G）以及 IP-over-InfiniBand。针对与这些网络类型，NetworkManager 可以配置他们的网络别名，IP 地址，静态路由，DNS，VPN连接以及很多其它的特殊参数。</p><p>可以用命令行工具 nmcli 来控制 NetworkManager。</p><p>###nmcli 用法###</p><pre><code># nmcli [ OPTIONS ] OBJECT { COMMAND | help }
</code></pre><p>我们可以通过 TAB 键补全命令，当你忘记这个命令的语法时只需要按下 TAB 就可以看到选项列表。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-tab.jpg" alt="nmcli tab"></p><p>使用 nmcli 的一些例子：</p><pre><code># nmcli general status
</code></pre><p>这条命令将 NetworkManager 的所有状态都打印出来。</p><pre><code># nmcli connection show
</code></pre><p>显示所有连接。</p><pre><code># nmcli connection show -a
</code></pre><p>仅显示当前活动的连接。</p><pre><code># nmcli device status
</code></pre><p>列出 NetworkManager 识别出的设备列表及他们的状态。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-gneral.jpg" alt="nmcli general"></p><h3 id="启动-停止-网络接口" tabindex="-1">启动/停止 网络接口### <a class="header-anchor" href="#启动-停止-网络接口" aria-label="Permalink to “启动/停止 网络接口###”">​</a></h3><p>使用 nmcli 工具启动或停止网络接口，与 ifconfig 的 up/down 是一样的。</p><p>使用下列命令停止某个接口：</p><pre><code># nmcli device disconnect eno16777736
</code></pre><p>下列命令用来启动接口：</p><pre><code># nmcli device connect eno16777736
</code></pre><p>###添加静态IP的以太网连接</p><p>以下命令可以添加一个静态IP地址的以太网连接：</p><pre><code># nmcli connection add type ethernet con-name NAME_OF_CONNECTION ifname interface-name ip4 IP_ADDRESS gw4 GW_ADDRESS
</code></pre><p>根据你需要的配置更改 NAME_OF_CONNECTION,IP_ADDRESS, GW_ADDRESS参数（如果不需要网关的话可以省略最后一部分）。</p><pre><code># nmcli connection add type ethernet con-name NEW ifname eno16777736 ip4 192.168.1.141 gw4 192.168.1.1
</code></pre><p>使用下列命令设置DNS服务器：</p><pre><code># nmcli connection modify NEW ipv4.dns &quot;8.8.8.8 8.8.4.4&quot;
</code></pre><p>下列命令启动新的 Ethernet 连接：</p><pre><code># nmcli connection up NEW ifname eno16777736
</code></pre><p>查看新连接的配置信息：</p><pre><code># nmcli -p connection show NEW
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-add-static.jpg" alt="nmcli add static"></p><p>###增加一个使用 DHCP 的新连接</p><p>增加新的连接，使用DHCP自动分配IP地址，网关，DNS等，你要做的就是将命令行后 ip/gw 地址部分去掉就行了，DHCP会自动分配这些参数。</p><p>例，在 eno 16777736 设备上配置一个 名为 NEW_DHCP 的 DHCP 连接</p><pre><code># nmcli connection add type ethernet con-name NEW_DHCP ifname eno16777736
</code></pre><hr>`,39)),t("p",null,[e[5]||(e[5]=n("via: ",-1)),i(o,{href:"http://linoxide.com/linux-command/nmcli-tool-red-hat-centos-7/"},{default:p(()=>[...e[4]||(e[4]=[n("http://linoxide.com/linux-command/nmcli-tool-red-hat-centos-7/",-1)])]),_:1})]),t("p",null,[e[9]||(e[9]=n("作者：",-1)),i(o,{href:"http://linoxide.com/author/adriand/"},{default:p(()=>[...e[6]||(e[6]=[n("Adrian Dinu",-1)])]),_:1}),e[10]||(e[10]=n(" 译者：",-1)),i(o,{href:"https://github.com/SPccman"},{default:p(()=>[...e[7]||(e[7]=[n("SPccman",-1)])]),_:1}),e[11]||(e[11]=n(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:p(()=>[...e[8]||(e[8]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=n("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[12]||(e[12]=[n("LCTT",-1)])]),_:1}),e[15]||(e[15]=n(" 原创翻译，",-1)),i(o,{href:"http://linux.cn/"},{default:p(()=>[...e[13]||(e[13]=[n("Linux中国",-1)])]),_:1}),e[16]||(e[16]=n(" 荣誉推出",-1))])])}const w=a(s,[["render",c]]);export{S as __pageData,w as default};
